import { index, jsonb, numeric, pgEnum, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { sources } from "@/app/lib/db/profile-schema";

export const ingestionMessageRole = pgEnum("ingestion_message_role", ["user", "assistant"]);
export const pendingChangeAction = pgEnum("pending_change_action", ["create", "update", "delete"]);
export const pendingChangeStatus = pgEnum("pending_change_status", ["pending", "approved", "rejected"]);

export const ingestionSessions = pgTable("ingestion_sessions", {
  // Generated by the browser when a session starts.
  id: uuid("id").primaryKey(),
  title: text("title").notNull(),
  // Rows approved from this session point at this source.
  sourceId: uuid("source_id").references(() => sources.id, { onDelete: "set null" }),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

export const ingestionMessages = pgTable(
  "ingestion_messages",
  {
    // The UI message id, so a resent message is stored once.
    id: text("id").primaryKey(),
    sessionId: uuid("session_id")
      .notNull()
      .references(() => ingestionSessions.id, { onDelete: "cascade" }),
    role: ingestionMessageRole("role").notNull(),
    // The UI message parts, tool calls included, so a reopened session shows what happened.
    parts: jsonb("parts").notNull(),
    costUsd: numeric("cost_usd", { precision: 12, scale: 8 }),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [
    index("ingestion_messages_session_id_idx").on(table.sessionId),
    index("ingestion_messages_created_at_idx").on(table.createdAt),
  ],
);

export const pendingChanges = pgTable(
  "pending_changes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    sessionId: uuid("session_id").references(() => ingestionSessions.id, { onDelete: "set null" }),
    profileTable: text("profile_table").notNull(),
    action: pendingChangeAction("action").notNull(),
    // The row an update or delete applies to.
    targetRowId: uuid("target_row_id"),
    // Form values (months as MM-YYYY, lists one per line). Empty for deletes.
    values: jsonb("values").$type<Record<string, string>>(),
    reason: text("reason"),
    status: pendingChangeStatus("status").default("pending").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    resolvedAt: timestamp("resolved_at"),
  },
  (table) => [index("pending_changes_status_idx").on(table.status)],
);
